90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OCTET_STRING: u8 = 0x04;
111	    const TAG_BOOLEAN: u8 = 0x01;
112	    const TAG_OID: u8 = 0x06;
113	    const TAG_SEQUENCE: u8 = 0x30;
114	    const TAG_SET: u8 = 0x31;
115	    const TAG_UTC_TIME: u8 = 0x17;
116	    const TAG_GENERALIZED_TIME: u8 = 0x18;
117	    const TAG_UTF8_STRING: u8 = 0x0C;
118	    const TAG_PRINTABLE_STRING: u8 = 0x13;
119	    const TAG_UNIVERSAL_STRING: u8 = 0x1C;
120	    const TAG_BMP_STRING: u8 = 0x1E;
121	
122	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
123	    /// length encodings and truncated data.
124	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
125	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
126	        if tag & 0x1F == 0x1F {
127	            return Err("multi-byte tags are not supported".to_string());
128	        }
129	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
130	        let (len, header_len) = match first_len {
131	            0x00..=0x7F => (first_len as usize, 2),
132	            0x80 => return Err("indefinite length is not valid DER".to_string()),
133	            0xFF => return Err("reserved length byte".to_string()),
134	            long => {
135	                let n = (long & 0x7F) as usize;
136	                if !(1..=4).contains(&n) {
137	                    return Err("length is too large".to_string());
138	                }
139	                let bytes = buf
140	                    .get(2..2 + n)
141	                    .ok_or_else(|| "truncated long length".to_string())?;
142	                if bytes[0] == 0 {
143	                    return Err("non-minimal length encoding".to_string());
144	                }
145	                let mut len = 0usize;
146	                for &b in bytes {
147	                    len = len
148	                        .checked_shl(8)
149	                        .and_then(|l| l.checked_add(b as usize))
150	                        .ok_or_else(|| "length overflow".to_string())?;
151	                }
152	                if len < 0x80 {
153	                    return Err("non-minimal length encoding".to_string());
154	                }
155	                (len, 2 + n)
156	            }
157	        };
158	        let total = header_len
159	            .checked_add(len)
160	            .filter(|&t| t <= buf.len())
161	            .ok_or_else(|| "truncated TLV content".to_string())?;
162	        Ok((
163	            Tlv {
164	                tag,
165	                content: &buf[header_len..total],
166	            },
167	            &buf[total..],
168	        ))
169	    }
170	
171	    fn read_tagged<'a>(
172	        buf: &'a [u8],
173	        tag: u8,
174	        what: &str,
175	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
176	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
177	        if tlv.tag != tag {
178	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
179	        }
180	        Ok((tlv, rest))
181	    }
182	
183	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
184	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
185	        // signatureValue BIT STRING } — and nothing trailing.
186	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
187	        if !rest.is_empty() {
188	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
189	        }
190	
191	        let c = cert.content;
192	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
193	        let (outer_alg, c) = read_tagged(c, TAG_SEQUENCE, "outer signatureAlgorithm")?;
194	        let outer_alg = parse_signature_algorithm(outer_alg, "outer signatureAlgorithm")?;
195	        let (sig_value, c) = read_tlv(c)?;
196	        if sig_value.tag != TAG_BIT_STRING {
197	            return Err("signature must be a BIT STRING".to_string());
198	        }
199	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
200	            return Err("invalid signature BIT STRING".to_string());
201	        }
202	        if !c.is_empty() {
203	            return Err("trailing data in Certificate".to_string());
204	        }
205	
206	        // TBSCertificate ::= SEQUENCE {
207	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
208	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
209	        let t = tbs.content;
210	        let (first, t2) = read_tlv(t)?;
211	        let (version, t) = if first.tag == 0xA0 {
212	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
213	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
214	                return Err("invalid certificate version".to_string());
215	            }
216	            (ver.content[0], t2)
217	        } else {
218	            // No explicit version: v1 certificate.
219	            (0u8, t)
220	        };
221	
222	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
223	        let t = t3;
224	        let (tbs_alg, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
225	        let tbs_alg = parse_signature_algorithm(tbs_alg, "tbs signatureAlgorithm")?;
226	        if tbs_alg != outer_alg {
227	            return Err(mismatch_message(&outer_alg, &tbs_alg));
228	        }
229	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
230	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
231	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
232	        let (spki, t_after_spki) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
233	        check_spki(spki)?;
234	        // Optional tail of TBSCertificate, in a fixed order:
235	        //   issuerUniqueID  [1] IMPLICIT BIT STRING  (v2/v3, at most once)
236	        //   subjectUniqueID [2] IMPLICIT BIT STRING  (v2/v3, at most once)
237	        //   extensions      [3] EXPLICIT             (v3 only, at most once,
238	        //                                             and the last field)
239	        // Nothing else may follow subjectPublicKeyInfo: fields cannot be
240	        // skipped, reordered or dropped. The extensions interior is decoded in
241	        // full by `check_extensions`; the unique IDs carry BIT STRING content
242	        // directly (implicit tagging), validated by `check_bit_string`.
243	        let mut t = t_after_spki;
244	        let mut issuer_uid_seen = false;
245	        let mut subject_uid_seen = false;
246	        let mut extensions_present = false;
247	        while !t.is_empty() {
248	            let tag_hint = t.first().copied();
249	            let (field, rest) = read_tlv(t).map_err(|e| match tag_hint {
250	                Some(0x81) => format!("issuerUniqueID: {e}"),
251	                Some(0x82) => format!("subjectUniqueID: {e}"),
252	                // A truncated field whose tag is already readable can still
253	                // be located: tag 0xA3 is the extensions field.
254	                Some(0xA3) => format!("extensions field: {e}"),
255	                _ => e,
256	            })?;
257	            match field.tag {
258	                0x81 | 0x82 => {
259	                    let what = if field.tag == 0x81 {
260	                        "issuerUniqueID"
261	                    } else {
262	                        "subjectUniqueID"
263	                    };
264	                    if version < 1 {
265	                        return Err(format!(
266	                            "{what} is only allowed in v2 or v3 certificates, this is v1"
267	                        ));
268	                    }
269	                    if extensions_present {
270	                        return Err(format!(
271	                            "{what} must appear before the extensions field, \
272	                             which is the last field of tbsCertificate"
273	                        ));
274	                    }
275	                    if field.tag == 0x81 {
276	                        if issuer_uid_seen {
277	                            return Err("duplicate issuerUniqueID field".to_string());
278	                        }
279	                        if subject_uid_seen {
280	                            return Err(
281	                                "issuerUniqueID must appear before subjectUniqueID".to_string()
282	                            );
283	                        }
284	                        issuer_uid_seen = true;
285	                    } else if subject_uid_seen {
286	                        return Err("duplicate subjectUniqueID field".to_string());
287	                    } else {
288	                        subject_uid_seen = true;
289	                    }
290	                    check_bit_string(field.content, what)?;
291	                }
292	                0xA1 | 0xA2 => {
293	                    let what = if field.tag == 0xA1 {
294	                        "issuerUniqueID"
295	                    } else {
296	                        "subjectUniqueID"
297	                    };
298	                    return Err(format!(
299	                        "{what} must be an implicitly tagged primitive BIT STRING \
300	                         (tag 0x{:02X}); constructed tag 0x{:02X} is an explicit wrapper \
301	                         and is not allowed",
302	                        field.tag - 0x20,
303	                        field.tag
304	                    ));
305	                }
306	                0xA3 => {
307	                    if extensions_present {
308	                        return Err("duplicate extensions field".to_string());
309	                    }
310	                    if version != 2 {
311	                        let name = if version == 0 {
312	                            "v1"
313	                        } else {
314	                            "v2"
315	                        };
316	                        return Err(format!(
317	                            "extensions are only allowed in v3 certificates, this is {name}"
318	                        ));
319	                    }
320	                    check_extensions(field.content)?;
321	                    extensions_present = true;
322	                }
323	                other => {
324	                    return Err(format!(
325	                        "unexpected field after subjectPublicKeyInfo (tag 0x{other:02X}): \
326	                         only issuerUniqueID [1], subjectUniqueID [2] and extensions [3] \
327	                         are allowed there, and extensions must be last"
328	                    ));
329	                }
330	            }
331	            t = rest;
332	        }
333	
334	        let serial_hex = format_serial(serial.content)?;
335	        let issuer = format_name(issuer, "issuer")?;
336	        let subject = format_name(subject, "subject")?;
337	
338	        let v = validity.content;
339	        let (nb, v2) = read_tlv(v)?;
340	        let (na, v3) = read_tlv(v2)?;
341	        if !v3.is_empty() {
342	            return Err("trailing data in validity".to_string());
343	        }
344	        let not_before = format_time(nb)?;
345	        let not_after = format_time(na)?;
346	
347	        Ok(Cert {
348	            subject,
349	            issuer,
350	            serial_hex,
351	            not_before,
352	            not_after,
353	        })
354	    }
355	
356	    /// Validate the content of the extensions field, i.e. the bytes wrapped
357	    /// by `[3] EXPLICIT`:
358	    ///
359	    /// ```text
360	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
361	    /// Extension  ::= SEQUENCE {
362	    ///   extnID    OBJECT IDENTIFIER,
363	    ///   critical  BOOLEAN DEFAULT FALSE,
364	    ///   extnValue OCTET STRING }
365	    /// ```
366	    ///
367	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
368	    /// Every extension must contain its OID and OCTET STRING in that order,
369	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
370	    /// Extension contents are never interpreted: unknown but well-formed
371	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
372	    ///
373	    /// Each extension type (its complete OID) may occur at most once in the
374	    /// list. Identity is the OID alone — critical flag, value content and
375	    /// value length never distinguish two entries — so a duplicate is neither
376	    /// picked between, merged nor dropped: the whole certificate is rejected,
377	    /// whether the duplicates are adjacent or separated by other extensions.
378	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
379	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
380	        if !rest.is_empty() {
381	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
382	        }
383	        if list.content.is_empty() {
384	            return Err("extensions SEQUENCE is empty".to_string());
385	        }
386	
387	        // Complete OIDs (parsed arcs) already seen in this list. DER mandates
388	        // one shortest encoding per OID and `parse_oid` enforces it, so equal
389	        // arcs mean the same OID regardless of raw bytes; the list is short,
390	        // a linear scan keeps the representation simple.
391	        let mut seen_oids: Vec<Vec<u64>> = Vec::new();
392	        let mut buf = list.content;
393	        while !buf.is_empty() {
394	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
395	            buf = rest;
396	
397	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
398	            let oid_arcs =
399	                parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
400	            if seen_oids.contains(&oid_arcs) {
401	                return Err(format!(
402	                    "duplicate extension type OID {}: an extension OID may appear at most once \
403	                     in the extensions list, regardless of its critical flag or extension value \
404	                     (duplicate entries are not selected between, merged or removed)",
405	                    arcs_to_string(&oid_arcs)
406	                ));
407	            }
408	            seen_oids.push(oid_arcs);
409	
410	            // critical is optional; whatever stands between the OID and the
411	            // OCTET STRING must be exactly one BOOLEAN if it is present.
412	            let (maybe_bool, after_critical) = read_tlv(after_oid)
413	                .map_err(|e| format!("extension after OID: {e}"))?;
414	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
415	                match maybe_bool.content {
416	                    [0xFF] => {}
417	                    [0x00] => {
418	                        return Err(
419	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
420	                                .to_string()
421	                        )
422	                    }
423	                    _ => {
424	                        return Err(
425	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
426	                        )
427	                    }
428	                }
429	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
430	            } else {
431	                // Not a BOOLEAN: this element must itself be the extnValue.
432	                if maybe_bool.tag != TAG_OCTET_STRING {
433	                    return Err(format!(
434	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
435	                         got tag 0x{:02X}",
436	                        maybe_bool.tag
437	                    ));
438	                }
439	                (maybe_bool, after_critical)
440	            };
441	            // An empty OCTET STRING is legal; its bytes are not interpreted.
442	            let _ = octets.content;
443	            if !after_octets.is_empty() {
444	                return Err("trailing data in extension".to_string());
445	            }
446	        }
447	        Ok(())
448	    }
449	
450	    /// SubjectPublicKeyInfo ::= SEQUENCE {
451	    ///   algorithm        AlgorithmIdentifier,
452	    ///   subjectPublicKey BIT STRING }
453	    /// Nothing may be missing and no extra elements may follow.
454	    fn check_spki(spki: Tlv) -> Result<(), String> {
455	        let (alg, rest) = read_tagged(
456	            spki.content,
457	            TAG_SEQUENCE,
458	            "subjectPublicKeyInfo algorithm identifier",
459	        )?;
460	        check_algorithm_identifier(alg)?;
461	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
462	        check_bit_string(key.content, "subjectPublicKey")?;
463	        if !rest.is_empty() {
464	            return Err("trailing data in subjectPublicKeyInfo".to_string());
465	        }
466	        Ok(())
467	    }
468	
469	    /// Why the content of an AlgorithmIdentifier SEQUENCE failed the shared
470	    /// structural check in `split_algorithm_identifier`. Each variant carries
471	    /// only the raw facts; every reader maps them onto its own established
472	    /// error wording (the public-key position names "algorithm OID" and
473	    /// "algorithm parameters", the signature algorithm positions name their
474	    /// own location).
475	    enum AlgIdError {
476	        /// The leading OID element could not be read as one complete TLV.
477	        OidRead(String),
478	        /// The first element is present but is not an OID.
479	        OidTag(u8),
480	        /// The OID element exists but its content is not a valid OID
481	        /// (empty, truncated or non-minimal base-128 arcs).
482	        OidContent(String),
483	        /// A parameter element follows the OID but cannot be read as one
484	        /// complete TLV.
485	        ParamsRead(String),
486	        /// Bytes remain after the parameter element: parameters are one
487	        /// OPTIONAL element, never several.
488	        ExtraAfterParams,
489	    }
490	
491	    /// Split the content of an AlgorithmIdentifier SEQUENCE into its
492	    /// algorithm OID and optional parameters, enforcing the structure every
493	    /// reader of an algorithm identifier shares:
494	    ///
495	    /// ```text
496	    /// AlgorithmIdentifier ::= SEQUENCE {
497	    ///   algorithm  OBJECT IDENTIFIER,
498	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
499	    /// ```
500	    ///
501	    /// The content must start with one complete, shortest-encoded OID,
502	    /// followed by either nothing or exactly one complete DER parameter
503	    /// value, and nothing after that. Absent parameters and an explicit NULL
504	    /// are both accepted and the parameter content is never interpreted for
505	    /// any particular algorithm; an unknown but well-formed OID is accepted.
506	    /// The parameter TLV is returned as its full original encoding (tag,
507	    /// length and content), sliced straight from the input, so callers that
508	    /// compare two identifiers can do so at the DER byte level.
509	    fn split_algorithm_identifier(
510	        content: &[u8],
511	    ) -> Result<(Tlv<'_>, Option<&[u8]>), AlgIdError> {
512	        let (oid, rest) = read_tlv(content).map_err(AlgIdError::OidRead)?;
513	        if oid.tag != TAG_OID {
514	            return Err(AlgIdError::OidTag(oid.tag));
515	        }
516	        parse_oid(oid.content).map_err(AlgIdError::OidContent)?;
517	        let params = if rest.is_empty() {
518	            None
519	        } else {
520	            let (_params, after) = read_tlv(rest).map_err(AlgIdError::ParamsRead)?;
521	            if !after.is_empty() {
522	                return Err(AlgIdError::ExtraAfterParams);
523	            }
524	            // Keep the full parameter TLV (tag, length and content), sliced
525	            // straight from the enclosing content; `read_tlv` already proved
526	            // it is a complete value.
527	            Some(&rest[..rest.len() - after.len()])
528	        };
529	        Ok((oid, params))
530	    }
531	
532	    /// Validate the AlgorithmIdentifier inside SubjectPublicKeyInfo: the
533	    /// shared structure from `split_algorithm_identifier`, reported with the
534	    /// public-key position's own wording.
535	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
536	        split_algorithm_identifier(alg.content)
537	            .map(|_| ())
538	            .map_err(|e| match e {
539	                AlgIdError::OidRead(e) => format!("algorithm OID: {e}"),
540	                AlgIdError::OidTag(tag) => {
541	                    format!("expected algorithm OID (tag 0x06), got 0x{tag:02X}")
542	                }
543	                AlgIdError::OidContent(e) => format!("algorithm OID: {e}"),
544	                AlgIdError::ParamsRead(e) => format!("algorithm parameters: {e}"),
545	                AlgIdError::ExtraAfterParams => "multiple algorithm parameters".to_string(),
546	            })
547	    }
548	
549	    /// One of the certificate's two signature algorithm descriptions, kept as
550	    /// raw slices so two copies can be compared at the DER byte level: the OID
551	    /// content (arcs in their shortest encoding) and the complete parameter
552	    /// TLV (tag, length and content), or no parameter at all. An absent
553	    /// parameter and an explicit NULL are different representations.
554	    #[derive(Clone, Copy, PartialEq, Eq)]
555	    struct SignatureAlgorithm<'a> {
556	        oid_content: &'a [u8],
557	        params: Option<&'a [u8]>,
558	    }
559	
560	    /// Parse and fully validate one signatureAlgorithm SEQUENCE, applying the
561	    /// shared AlgorithmIdentifier structure from `split_algorithm_identifier`
562	    /// and keeping the raw pieces for the byte-level comparison of the two
563	    /// copies. `loc` names which of the two copies is being checked ("outer
564	    /// signatureAlgorithm" or the copy inside tbsCertificate) and prefixes
565	    /// every error message.
566	    fn parse_signature_algorithm<'a>(
567	        alg: Tlv<'a>,
568	        loc: &str,
569	    ) -> Result<SignatureAlgorithm<'a>, String> {
570	        let (oid, params) = split_algorithm_identifier(alg.content).map_err(|e| match e {
571	            AlgIdError::OidRead(e) => format!("{loc}: {e}"),
572	            AlgIdError::OidTag(tag) => format!(
573	                "{loc}: algorithm must start with an OID (tag 0x06), got tag 0x{tag:02X}"
574	            ),
575	            AlgIdError::OidContent(e) => format!("{loc}: {e}"),
576	            AlgIdError::ParamsRead(e) => format!("{loc}: algorithm parameters: {e}"),
577	            AlgIdError::ExtraAfterParams => {
578	                format!("{loc}: extra element after the algorithm parameters")
579	            }
580	        })?;
581	        Ok(SignatureAlgorithm {
582	            oid_content: oid.content,
583	            params,
584	        })
585	    }
586	
587	    /// Describe the disagreement between the outer signatureAlgorithm and the
588	    /// copy inside tbsCertificate. Both copies parse on their own; they merely
589	    /// fail to name the same algorithm or the same parameter representation.
590	    fn mismatch_message(outer: &SignatureAlgorithm<'_>, inner: &SignatureAlgorithm<'_>) -> String {
591	        const OUTER: &str = "the outer signatureAlgorithm";
592	        const INNER: &str = "the signatureAlgorithm in tbsCertificate";
593	        if outer.oid_content != inner.oid_content {
594	            let outer_oid = parse_oid(outer.oid_content)
595	                .map(|arcs| arcs_to_string(&arcs))
596	                .unwrap_or_else(|_| "?".to_string());
597	            let inner_oid = parse_oid(inner.oid_content)
598	                .map(|arcs| arcs_to_string(&arcs))
599	                .unwrap_or_else(|_| "?".to_string());
600	            return format!(
601	                "signature algorithm mismatch: {OUTER} names OID {outer_oid}, but {INNER} \
602	                 names OID {inner_oid}"
603	            );
604	        }
605	        match (outer.params, inner.params) {
606	            (Some(outer_params), Some(inner_params)) if outer_params != inner_params => {
607	                format!(
608	                    "signature algorithm mismatch: both copies name the same algorithm OID but \
609	                     their parameters have different DER encodings ({OUTER} has {}, {INNER} has {})",
610	                    hex_of(outer_params),
611	                    hex_of(inner_params),
612	                )
613	            }
614	            (Some(_), None) => format!(
615	                "signature algorithm mismatch: {OUTER} carries parameters but {INNER} omits them \
616	                 (an absent parameter and an explicit value are different representations)"
617	            ),
618	            (None, Some(_)) => format!(
619	                "signature algorithm mismatch: {INNER} carries parameters but {OUTER} omits them \
620	                 (an absent parameter and an explicit value are different representations)"
621	            ),
622	            // PartialEq already proved the copies unequal; reaching any other
623	            // arm here would be a logic error rather than a malformed cert.
624	            _ => "signature algorithm mismatch between the two signatureAlgorithm copies"
625	                .to_string(),
626	        }
627	    }
