629	    fn hex_of(bytes: &[u8]) -> String {
630	        let mut s = String::with_capacity(bytes.len() * 2);
631	        for b in bytes {
632	            write!(s, "{b:02X}").unwrap();
633	        }
634	        s
635	    }
