637	    /// Validate the DER content of a BIT STRING: one leading byte counting
638	    /// unused bits (0..=7), and when the count is nonzero those low bits of
639	    /// the final data byte must all be zero. An empty bit string is only
640	    /// legal with a zero count.
641	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
642	        let unused = *content
643	            .first()
644	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
645	        if unused > 7 {
646	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
647	        }
648	        let data = &content[1..];
649	        if data.is_empty() {
650	            if unused != 0 {
651	                return Err(format!(
652	                    "{what} BIT STRING declares {unused} unused bits but has no data"
653	                ));
654	            }
655	            return Ok(());
656	        }
657	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
658	            return Err(format!(
659	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
660	            ));
661	        }
662	        Ok(())
663	    }
