665	    /// Render the serial number as upper-case hex, matching the integer value
666	    /// (a DER sign-padding 0x00 byte is not part of the number).
667	    fn format_serial(content: &[u8]) -> Result<String, String> {
668	        if content.is_empty() {
669	            return Err("empty serial number".to_string());
670	        }
671	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
672	            return Err("non-minimal serial number encoding".to_string());
673	        }
674	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
675	            return Err("non-minimal serial number encoding".to_string());
676	        }
677	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
678	            return Err("negative serial number".to_string());
679	        }
680	        let digits = if content.len() > 1 && content[0] == 0x00 {
681	            &content[1..]
682	        } else {
683	            content
684	        };
685	        let mut s = String::with_capacity(digits.len() * 2);
686	        for b in digits {
687	            write!(s, "{b:02X}").unwrap();
688	        }
689	        if s.is_empty() {
690	            s.push_str("00");
691	        }
692	        Ok(s)
693	    }
