695	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
696	    /// multi-valued RDNs joined with '+'). Values of known attribute types
697	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
698	    /// when their tag has a text decoder; a known type carrying any other
699	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
700	    /// name and uses the '#' form carrying the value's full DER encoding in
701	    /// hex. Attributes without a known short name use their dotted OID with
702	    /// the same '#' form.
703	    ///
704	    /// Each RDN is a DER SET OF, so its complete AttributeTypeAndValue
705	    /// encodings must be sorted by their full encoding bytes (tag, then
706	    /// length, then content — the encoding, never the display name, dotted
707	    /// OID text or decoded value). The check is per RDN; it never reorders
708	    /// the members itself. `what` names the name being checked ("subject" or
709	    /// "issuer") so an ordering failure identifies it in the error message.
710	    fn format_name(name: Tlv, what: &str) -> Result<String, String> {
711	        let mut rdn_buf = name.content;
712	        let mut rdns: Vec<String> = Vec::new();
713	        while !rdn_buf.is_empty() {
714	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
715	            rdn_buf = rest;
716	
717	            let mut atv_buf = set.content;
718	            let mut parts = Vec::new();
719	            // Raw full encoding (tag, length and content) of each member of
720	            // this SET OF, straight from the certificate: DER SET OF ordering
721	            // compares the complete member encodings byte for byte. Equal
722	            // encodings may legitimately repeat and stay adjacent.
723	            let mut members: Vec<&[u8]> = Vec::new();
724	            while !atv_buf.is_empty() {
725	                let atv_start = atv_buf;
726	                let (atv, rest) =
727	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
728	                atv_buf = rest;
729	                members.push(&atv_start[..atv_start.len() - atv_buf.len()]);
730	
731	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
732	                let (value, after_value) = read_tlv(after_oid)?;
733	                if !after_value.is_empty() {
734	                    return Err("trailing data in attribute value".to_string());
735	                }
736	
737	                let oid_arcs = parse_oid(oid.content)?;
738	
739	                // The value's own string-type rules are applied exactly once,
740	                // here, before any display decision and regardless of whether
741	                // the attribute later renders as text for a known short name
742	                // or as '#'-hex for an unknown type: a UTF8String must hold
743	                // valid UTF-8, a PrintableString must keep to its alphabet, a
744	                // BMPString must hold whole 16-bit non-surrogate characters
745	                // and a UniversalString must hold whole, in-range Unicode
746	                // code points. The hex form must never let an illegal byte or
747	                // code point through, and illegal content cannot be dropped or
748	                // replaced. An empty value stays legal. Tags without string
749	                // rules (SEQUENCE, OCTET STRING, ...) pass untouched and are
750	                // simply not text-decodable. `what` names the offending name
751	                // ("subject"/"issuer").
752	                let text = check_attribute_string(value, what)?;
753	
754	                match oid_short_name(&oid_arcs) {
755	                    Some(label) => match text {
756	                        // Supported string type: decode to escaped text.
757	                        Some(text) => parts.push(format!("{label}={}", escape_value(&text))),
758	                        // Known type but a legal value with no text decoder
759	                        // (SEQUENCE, OCTET STRING, ...): keep the short name
760	                        // and show the full original DER encoding as '#'-hex.
761	                        None => {
762	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)))
763	                        }
764	                    },
765	                    None => {
766	                        // Unknown attribute type: RFC 4514 requires the form
767	                        // OID=#hex, where the hex is the full DER encoding
768	                        // (tag, length and content) of the attribute value.
769	                        // The value is still a string governed by its type
770	                        // rules, already checked once above; whether it
771	                        // decoded to text never affects this hex display.
772	                        let hex = value_hex(after_oid, after_value);
773	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
774	                    }
775	                }
776	            }
777	            if parts.is_empty() {
778	                return Err("empty RelativeDistinguishedName".to_string());
779	            }
780	            check_rdn_der_order(&members, what)?;
781	            rdns.push(parts.join("+"));
782	        }
783	        rdns.reverse();
784	        Ok(rdns.join(","))
785	    }
786	
787	    /// Validate one RDN as a DER SET OF: every member's complete
788	    /// AttributeTypeAndValue encoding must be less than or equal to the next
789	    /// one under ordinary byte ordering of tag, length and content. The
790	    /// comparison runs on the raw encodings only — CN/O short names, dotted
791	    /// OID text and decoded values never enter into it — and equal adjacent
792	    /// members (duplicate attributes) are allowed. The members are never
793	    /// reordered to make an unsorted input pass. `what` is "subject" or
794	    /// "issuer" and identifies the offending name in the error message.
795	    fn check_rdn_der_order(members: &[&[u8]], what: &str) -> Result<(), String> {
796	        for pair in members.windows(2) {
797	            if pair[0] > pair[1] {
798	                return Err(format!(
799	                    "{what} name: attributes of a multi-valued RelativeDistinguishedName \
800	                     are not encoded in DER SET OF order (the members must be sorted by \
801	                     their complete DER encoding bytes: tag, then length, then content)"
802	                ));
803	            }
804	        }
805	        Ok(())
806	    }
807	
808	    /// Uppercase hex of one complete value TLV, sliced straight from the
809	    /// input bytes (`around` ends at `rest`). The original tag and length
810	    /// bytes survive verbatim, including a legal long-form length; nothing is
811	    /// re-encoded and content alone is never emitted.
812	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
813	        let tlv_len = around.len() - rest.len();
814	        let mut hex = String::with_capacity(tlv_len * 2);
815	        for b in &around[..tlv_len] {
816	            write!(hex, "{b:02X}").unwrap();
817	        }
818	        hex
819	    }
820	
821	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
822	        if content.is_empty() {
823	            return Err("empty OID".to_string());
824	        }
825	        let mut arcs = Vec::new();
826	        // The first subidentifier encodes the first two arcs as
827	        // 40*first + second and is itself a base-128 quantity, so it can
828	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
829	        let mut i = 0;
830	        let first = read_oid_arc(content, &mut i)?;
831	        match first {
832	            0..=39 => {
833	                arcs.push(0);
834	                arcs.push(first);
835	            }
836	            40..=79 => {
837	                arcs.push(1);
838	                arcs.push(first - 40);
839	            }
840	            _ => {
841	                arcs.push(2);
842	                arcs.push(first - 80);
843	            }
844	        }
845	        while i < content.len() {
846	            arcs.push(read_oid_arc(content, &mut i)?);
847	        }
848	        Ok(arcs)
849	    }
850	
851	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
852	    /// continuation bytes and non-minimal encodings.
853	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
854	        let start = *i;
855	        let mut value = 0u64;
856	        loop {
857	            let b = *content
858	                .get(*i)
859	                .ok_or_else(|| "truncated OID arc".to_string())?;
860	            value = value
861	                .checked_mul(128)
862	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
863	                .ok_or_else(|| "OID arc overflow".to_string())?;
864	            *i += 1;
865	            if b & 0x80 == 0 {
866	                break;
867	            }
868	        }
869	        if *i - start > 1 && content[start] == 0x80 {
870	            return Err("non-minimal OID arc encoding".to_string());
871	        }
872	        Ok(value)
873	    }
874	
875	    fn arcs_to_string(arcs: &[u64]) -> String {
876	        arcs.iter()
877	            .map(u64::to_string)
878	            .collect::<Vec<_>>()
879	            .join(".")
880	    }
