882	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
883	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
884	        let name = match arcs {
885	            [2, 5, 4, 3] => "CN",
886	            [2, 5, 4, 4] => "SN",
887	            [2, 5, 4, 5] => "serialNumber",
888	            [2, 5, 4, 6] => "C",
889	            [2, 5, 4, 7] => "L",
890	            [2, 5, 4, 8] => "ST",
891	            [2, 5, 4, 9] => "STREET",
892	            [2, 5, 4, 10] => "O",
893	            [2, 5, 4, 11] => "OU",
894	            [2, 5, 4, 12] => "title",
895	            [2, 5, 4, 17] => "postalAddress",
896	            [2, 5, 4, 18] => "postalCode",
897	            [2, 5, 4, 20] => "telephoneNumber",
898	            [2, 5, 4, 42] => "givenName",
899	            [2, 5, 4, 43] => "initials",
900	            [2, 5, 4, 44] => "generationQualifier",
901	            [2, 5, 4, 46] => "dnQualifier",
902	            [2, 5, 4, 65] => "pseudonym",
903	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
904	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
905	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
906	            _ => return None,
907	        };
908	        Some(name)
909	    }
