911	    /// Whether every byte belongs to the RFC 5280 PrintableString alphabet:
912	    /// A-Z, a-z, 0-9, space, and ' ( ) + , - . / : = ?. Every other byte
913	    /// (including @, _, tabs, newlines, NUL and 0x80..=0xFF) is illegal.
914	    /// An empty value passes, preserving the existing acceptance of empty
915	    /// contents.
916	    fn is_printable_string(content: &[u8]) -> bool {
917	        content.iter().all(|&b| matches!(
918	            b,
919	            b'A'..=b'Z'
920	                | b'a'..=b'z'
921	                | b'0'..=b'9'
922	                | b' '
923	                | b'\''
924	                | b'('
925	                | b')'
926	                | b'+'
927	                | b','
928	                | b'-'
929	                | b'.'
930	                | b'/'
931	                | b':'
932	                | b'='
933	                | b'?'
934	        ))
935	    }
936	
937	    /// Validate BMPString content and decode it to UTF-8 text in one pass: an
938	    /// even number of bytes read as big-endian 16-bit characters, each of
939	    /// which must be a Basic Multilingual Plane code point
940	    /// (U+0000..=U+FFFF) and never a UTF-16 surrogate (U+D800..=U+DFFF).
941	    /// Surrogates are not characters, so a lone high or low surrogate is
942	    /// corrupt, and so is an adjacent pair that UTF-16 rules would combine
943	    /// into an astral-plane character — the pair must not be merged and
944	    /// displayed. An illegal value fails the whole certificate; bytes are
945	    /// never dropped or replaced to salvage it. Empty content stays legal,
946	    /// preserving the existing acceptance of empty values. `what` names the
947	    /// name being checked ("subject"/"issuer") so the error identifies the
948	    /// offending name.
949	    fn decode_bmp_string(content: &[u8], what: &str) -> Result<String, String> {
950	        if content.len() % 2 != 0 {
951	            return Err(format!(
952	                "{what} name: BMPString attribute value has an odd length of {} byte(s) \
953	                 (the content must be a sequence of 16-bit characters)",
954	                content.len()
955	            ));
956	        }
957	        // A BMPString character is one big-endian 16-bit BMP code point, never
958	        // a UTF-16 surrogate: surrogate pairs must not be merged into
959	        // astral-plane characters.
960	        let mut s = String::with_capacity(content.len() / 2);
961	        for pair in content.chunks_exact(2) {
962	            let unit = u16::from_be_bytes([pair[0], pair[1]]);
963	            if (0xD800..=0xDFFF).contains(&unit) {
964	                return Err(format!(
965	                    "{what} name: BMPString attribute value contains the surrogate code \
966	                     point U+{unit:04X}, which is not a legal character (U+D800..=U+DFFF \
967	                     are not characters and cannot appear, alone or in pairs)"
968	                ));
969	            }
970	            // Not a surrogate, so every 16-bit unit is a valid scalar value.
971	            s.push(char::from_u32(unit as u32).unwrap());
972	        }
973	        Ok(s)
974	    }
975	
976	    /// Validate UniversalString content and decode it to UTF-8 text in one
977	    /// pass: the bytes must form whole big-endian 32-bit Unicode code points,
978	    /// so the length must be a multiple of four, and every code point must lie
979	    /// in U+0000..=U+10FFFF and never be a UTF-16 surrogate
980	    /// (U+D800..=U+DFFF). A trailing incomplete unit, a lone surrogate (or a
981	    /// pair that UTF-16 rules would combine), or a value above the Unicode
982	    /// ceiling is corrupt; the whole certificate fails and no unit is dropped,
983	    /// replaced or merely hex-displayed to salvage it. Empty content stays
984	    /// legal, preserving the existing acceptance of empty values. `what` names
985	    /// the name being checked ("subject"/"issuer") so the error identifies the
986	    /// offending name.
987	    fn decode_universal_string(content: &[u8], what: &str) -> Result<String, String> {
988	        if content.len() % 4 != 0 {
989	            return Err(format!(
990	                "{what} name: UniversalString attribute value has a length of {} byte(s), \
991	                 which is not a multiple of four (the content must be a sequence of \
992	                 big-endian 32-bit Unicode code points)",
993	                content.len()
994	            ));
995	        }
996	        let mut s = String::new();
997	        for unit in content.chunks_exact(4) {
998	            let cp = u32::from_be_bytes([unit[0], unit[1], unit[2], unit[3]]);
999	            if (0xD800..=0xDFFF).contains(&cp) {
1000	                return Err(format!(
1001	                    "{what} name: UniversalString attribute value contains the surrogate code \
1002	                     point U+{cp:04X}, which is not a legal character (U+D800..=U+DFFF are \
1003	                     not characters and cannot appear, alone or in pairs)"
1004	                ));
1005	            }
1006	            if cp > 0x10FFFF {
1007	                return Err(format!(
1008	                    "{what} name: UniversalString attribute value contains the code point \
1009	                     U+{cp:04X}, which is above the Unicode maximum U+10FFFF"
1010	                ));
1011	            }
1012	            s.push(char::from_u32(cp).unwrap());
1013	        }
1014	        Ok(s)
1015	    }
1016	
1017	    /// Validate one name attribute value against the rules of its own string
1018	    /// type and, when it is a supported string type, decode it to UTF-8 text.
1019	    ///
1020	    /// This is the single place that owns each supported string type's rules
1021	    /// (valid UTF-8, the PrintableString alphabet, whole BMP characters
1022	    /// without surrogates, whole in-range UniversalString code points) and the
1023	    /// single place that decodes them, so the legality check and the text
1024	    /// decoding can never drift apart. It runs once per attribute, before any
1025	    /// display decision and regardless of whether the attribute later renders
1026	    /// as text for a known short name or as '#'-hex for an unknown type:
1027	    /// showing a value as hex must never let an illegal byte or code point
1028	    /// through, and illegal content cannot be dropped or replaced.
1029	    ///
1030	    /// Returns `Ok(Some(text))` for a supported, valid string type, and
1031	    /// `Ok(None)` for any other tag (a legal DER value with no text decoder —
1032	    /// a SEQUENCE, OCTET STRING, … — which the caller renders as '#'-hex). An
1033	    /// empty string value is legal and decodes to empty text. `what` names the
1034	    /// name being checked ("subject"/"issuer") so an error identifies it.
1035	    fn check_attribute_string(value: Tlv, what: &str) -> Result<Option<String>, String> {
1036	        let content = value.content;
1037	        let text = match value.tag {
1038	            TAG_UTF8_STRING => std::str::from_utf8(content)
1039	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
1040	                .to_string(),
1041	            TAG_PRINTABLE_STRING => {
1042	                if !is_printable_string(content) {
1043	                    return Err(format!(
1044	                        "{what} name: PrintableString attribute value contains an illegal \
1045	                         character (only A-Z, a-z, 0-9, space and ' ( ) + , - . / : = ? are \
1046	                         allowed)"
1047	                    ));
1048	                }
1049	                // ASCII-family: after the alphabet check every byte is also
1050	                // its Unicode code point.
1051	                content.iter().map(|&b| b as char).collect()
1052	            }
1053	            // NumericString (0x12), IA5String (0x16) and VisibleString (0x1A)
1054	            // are ASCII-family strings: every byte is also its Unicode code
1055	            // point and they carry no extra character rule here.
1056	            0x12 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
1057	            // T.61/TeletexString (0x14) and GeneralString (0x1B) are
1058	            // conventionally treated as Latin-1 here: the byte value is the
1059	            // code point and they carry no extra character rule here.
1060	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
1061	            TAG_BMP_STRING => decode_bmp_string(content, what)?,
1062	            TAG_UNIVERSAL_STRING => decode_universal_string(content, what)?,
1063	            // Any other readable DER value (SEQUENCE, OCTET STRING, ...) is a
1064	            // legal non-text attribute value: it has no string rule to apply
1065	            // and no text decoder, so it is rendered from its original DER as
1066	            // '#'-hex.
1067	            _ => return Ok(None),
1068	        };
1069	        Ok(Some(text))
1070	    }
1071	
1072	    /// RFC 4514 value escaping; everything above the ASCII control range
1073	    /// (including CJK text) passes through unchanged.
1074	    fn escape_value(value: &str) -> String {
1075	        let mut out = String::with_capacity(value.len());
1076	        let last = value.chars().count().saturating_sub(1);
1077	        for (i, c) in value.chars().enumerate() {
1078	            let at_edge = i == 0 || i == last;
1079	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
1080	                || (at_edge && (c == ' ' || c == '#'));
1081	            if needs_backslash {
1082	                out.push('\\');
1083	                out.push(c);
1084	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
1085	                let mut buf = [0u8; 4];
1086	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
1087	                write!(out, "\\{b:02X}").unwrap();
1088	            } else {
1089	                out.push(c);
1090	            }
1091	        }
1092	        out
1093	    }
1094	
1095	    fn format_time(tlv: Tlv) -> Result<String, String> {
1096	        let (y, mo, d, h, mi, se) = match tlv.tag {
1097	            TAG_UTC_TIME => {
1098	                let c = tlv.content;
1099	                if c.len() != 13 || c[12] != b'Z' {
1100	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
1101	                }
1102	                let digits = &c[..12];
1103	                if !digits.iter().all(|b| b.is_ascii_digit()) {
1104	                    return Err("non-numeric UTCTime".to_string());
1105	                }
1106	                let n = |a: usize, b: usize| -> u32 {
1107	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
1108	                };
1109	                let yy = n(0, 1);
1110	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
1111	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
1112	            }
1113	            TAG_GENERALIZED_TIME => {
1114	                let c = tlv.content;
1115	                if c.len() != 15 || c[14] != b'Z' {
1116	                    return Err(
1117	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
1118	                    );
1119	                }
1120	                let digits = &c[..14];
1121	                if !digits.iter().all(|b| b.is_ascii_digit()) {
1122	                    return Err("non-numeric GeneralizedTime".to_string());
1123	                }
1124	                let n = |a: usize, b: usize| -> u32 {
1125	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
1126	                };
1127	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
1128	            }
1129	            other => return Err(format!("invalid time tag 0x{other:02X}")),
1130	        };
1131	        validate_datetime(y, mo, d, h, mi, se)?;
1132	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
1133	    }
1134	
1135	    fn validate_datetime(
1136	        year: i32,
1137	        month: u32,
1138	        day: u32,
1139	        hour: u32,
1140	        minute: u32,
1141	        second: u32,
1142	    ) -> Result<(), String> {
1143	        if !(1..=12).contains(&month) {
1144	            return Err("invalid month in certificate time".to_string());
1145	        }
1146	        if hour > 23 || minute > 59 || second > 59 {
1147	            return Err("invalid time of day in certificate time".to_string());
1148	        }
1149	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
1150	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
1151	        if day < 1 || day > days[(month - 1) as usize] {
1152	            return Err("invalid day in certificate time".to_string());
1153	        }
1154	        Ok(())
1155	    }
