1118	// ----- Certificate / DER construction -------------------------------------
1119	//
1120	// Only the structural pieces needed here. Lengths are always emitted in the
1121	// minimal DER form, except where a test injects raw bytes to exercise
1122	// rejection of non-minimal or truncated encodings.
1123	
1124	fn simple_cn_name(cn: &str) -> Vec<u8> {
1125	    name(&[rdn(&[atv_utf8(CN, cn)])])
1126	}
1127	
1128	/// Assemble a complete, parseable v1 DER certificate with fixed serial,
1129	/// validity and key material around the supplied Subject/Issuer names.
1130	fn build_cert(subject: &[u8], issuer: &[u8]) -> Vec<u8> {
1131	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
1132	    let validity = seq(&concat(&[
1133	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
1134	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
1135	    ]));
1136	    let spki = seq(&concat(&[
1137	        &seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 1]), &tlv(0x05, &[])])),
1138	        &tlv(0x03, &[0x00, 0x01, 0x00]), // BIT STRING, zero unused bits
1139	    ]));
1140	
1141	    let tbs = seq(&concat(&[
1142	        &serial,
1143	        &signature_algorithm(),
1144	        issuer,
1145	        &validity,
1146	        subject,
1147	        &spki,
1148	    ]));
1149	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
1150	}
1151	
1152	fn signature_algorithm() -> Vec<u8> {
1153	    // sha256WithRSAEncryption with explicit NULL parameters.
1154	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
1155	}
