    let mut inner = oid(&[1, 2, 3, 4]);
    inner.extend_from_slice(&[0x0C, 0x81, 0x03, 0x61, 0x62, 0x63]);
    let subject = name(&[rdn(&[seq(&inner)])]);
    let issuer = simple_cn_name("Test CA");
